  {"id":"ibn-battuta-1325","titel":"Ibn Battutas erste große Reise","von":1325,"bis":1330,"vertiefung":null,"beschreibung":"1325 bricht Ibn Battuta aus Tanger zur Pilgerfahrt nach Mekka auf und reist anschließend durch Irak und Persien. Von Mekka aus fährt er über das Rote Meer und Aden an die ostafrikanische Swahili-Küste bis Kilwa.","quelle":"Ross E. Dunn, The Adventures of Ibn Battuta (1986), aufbereitet von ORIAS, UC Berkeley ('The Travels of Ibn Battuta: A Virtual Tour'); Reihenfolge nach der Rihla. Jahreszahlen folgen Dunn; die Chronologie ist in der Forschung teils umstritten.","stationen":[{"ort":"Tanger","jahr":1325,"was":"Aufbruch zur Pilgerfahrt (Juni)","genau":"ort","quelle":"https://en.wikipedia.org/wiki/Tangier","lon":-5.804,"lat":35.777,"x":484.9,"y":137.3},{"ort":"Kairo","jahr":1326,"was":"Aufenthalt in der Mamlukenhauptstadt","genau":"ort","quelle":"https://en.wikipedia.org/wiki/Cairo","lon":31.236,"lat":30.044,"x":583,"y":155.8},{"ort":"Damaskus","jahr":1326,"was":"Ramadan in Damaskus, Anschluss an die Pilgerkarawane","genau":"ort","quelle":"https://en.wikipedia.org/wiki/Damascus","lon":36.309,"lat":33.513,"x":595.4,"y":144.6},{"ort":"Mekka","jahr":1326,"was":"Erste Pilgerfahrt (Hadsch)","genau":"ort","quelle":"https://en.wikipedia.org/wiki/Mecca","lon":39.823,"lat":21.423,"x":608.2,"y":183.7},{"ort":"Bagdad","jahr":1327,"was":"Nach Nadschaf, Basra, Isfahan und Schiras; Anschluss an die Karawane des Ilchans","genau":"ort","quelle":"https://en.wikipedia.org/wiki/Baghdad","lon":44.366,"lat":33.315,"x":616.7,"y":145.2},{"ort":"Täbris","jahr":1327,"was":"Kurzer Aufenthalt mit dem Hof des Ilchans","genau":"ort","quelle":"https://en.wikipedia.org/wiki/Tabriz","lon":46.3,"lat":38.067,"x":619.6,"y":129.9},{"ort":"Mekka","jahr":1327,"was":"Rückkehr und längerer Aufenthalt","genau":"ort","quelle":"https://en.wikipedia.org/wiki/Mecca","lon":39.823,"lat":21.423,"x":608.2,"y":183.7},{"ort":"Aden","jahr":1328,"was":"Über Dschidda und Ta'izz zum Hafen Aden","genau":"ort","hinweis":"Abschnitt Rotes Meer–Ostafrika 1328–1330 nach Dunn; genaues Jahr je Station unsicher, ältere Chronologie (Gibb) datiert ihn auf 1330–1332","quelle":"https://en.wikipedia.org/wiki/Aden","lon":45.033,"lat":12.8,"x":624.1,"y":211.5},{"ort":"Mogadischu","jahr":1328,"was":"Besuch des Sultans","genau":"ort","hinweis":"Jahr wie bei Aden unsicher (1328–1330)","quelle":"https://en.wikipedia.org/wiki/Mogadishu","lon":45.342,"lat":2.039,"x":625.9,"y":246.1},{"ort":"Kilwa","jahr":1328,"was":"Südlichster Punkt der Reise, etwa zwei Wochen Aufenthalt","genau":"ort","hinweis":"Jahr wie bei Aden unsicher (1328–1330)","quelle":"https://en.wikipedia.org/wiki/Kilwa_Kisiwani","lon":39.513,"lat":-8.96,"x":609.3,"y":281.5}],"linien":[[[484.9,137.3],[583,155.8],[595.4,144.6],[608.2,183.7],[616.7,145.2],[619.6,129.9],[608.2,183.7],[624.1,211.5],[625.9,246.1],[609.3,281.5]]],"seit":"2026-10-04"}
